function bondPrice(face, couponRate, ytm, years, freq){
  face=(+face)||1000; couponRate=(+couponRate); if(isNaN(couponRate))couponRate=0;
  ytm=(+ytm); if(isNaN(ytm))ytm=0; years=(+years)||1; freq=(+freq)||2;
  if(freq<1) freq=1;
  var n=Math.round(years*freq);
  var periodRate=ytm/freq;
  var coupon=face*couponRate/freq;
  var price=0;
  for(var t=1;t<=n;t++){ price+=coupon/Math.pow(1+periodRate,t); }
  price+=face/Math.pow(1+periodRate,n);
  price=Math.round(price*100)/100;
  return {price:price, face:face, ytm:ytm, years:years, freq:freq, status:(price>face?'溢价':(price<face?'折价':'平价'))};
}
var EXPORTS={bondPrice:bondPrice};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BondPricingForgePure = EXPORTS; }
